(*
  Statement-only formalization of VERINA corpus artifact verina_advanced_19,
  catalog title "isCleanPalindrome": an executable test filters a string to
  lowercase ASCII letters and checks the resulting character list for being a
  palindrome, together with its total correctness contract. This file contains
  no proof.
*)

let isCleanPalindrome_validChar = new_definition
  `isCleanPalindrome_validChar (c:num) <=>
     c < 55296 \/ (57343 < c /\ c < 1114112)`;;

let isCleanPalindrome_string = new_definition
  `isCleanPalindrome_string (s:num list) <=>
     ALL isCleanPalindrome_validChar s`;;

let isUpperAlpha = new_definition
  `isUpperAlpha (c:num) <=> 65 <= c /\ c <= 90`;;

let isLowerAlpha = new_definition
  `isLowerAlpha (c:num) <=> 97 <= c /\ c <= 122`;;

let isAlpha = new_definition
  `isAlpha (c:num) <=> isUpperAlpha c \/ isLowerAlpha c`;;

let toLower = new_definition
  `toLower (c:num) =
     if isUpperAlpha c then c + 32 else c`;;

let normalizeChar = new_definition
  `normalizeChar (c:num) =
     if isAlpha c then SOME (toLower c) else NONE`;;

let normalizeString_step =
  new_recursive_definition option_RECURSION
    `(!acc:num list.
        normalizeString_step (NONE:num option) acc = acc) /\
     (!c:num. !acc:num list.
        normalizeString_step (SOME c) acc = CONS c acc)`;;

let normalizeString =
  new_recursive_definition list_RECURSION
    `(normalizeString ([]:num list) = []) /\
     (!c:num. !cs:num list.
        normalizeString (CONS c cs) =
        normalizeString_step
          (normalizeChar c) (normalizeString cs))`;;

let isCleanPalindrome_precond = new_definition
  `isCleanPalindrome_precond (s:num list) <=> T`;;

let reverseList = new_definition
  `reverseList (xs:num list) = REVERSE xs`;;

let isCleanPalindrome = new_definition
  `isCleanPalindrome (s:num list) =
     let norm = normalizeString s in
     norm = reverseList norm`;;

let isCleanPalindrome_postcond = new_definition
  `isCleanPalindrome_postcond (s:num list) (result:bool) <=>
     let norm = normalizeString s in
     (result = T ==> norm = REVERSE norm) /\
     (result = F ==> ~(norm = REVERSE norm))`;;

let isCleanPalindrome_spec_satisfied =
  `!s:num list.
     isCleanPalindrome_string s
     ==> isCleanPalindrome_precond s
     ==> isCleanPalindrome_postcond s (isCleanPalindrome s)`;;

(*
  Statement-only formalization of VERINA artifact verina_advanced_19,
  cataloged as "isCleanPalindrome": the executable Boolean program tests
  whether the Unicode-scalar string's ASCII letters form a
  case-insensitive palindrome after all other characters are removed.
  This file contains no proof.
*)

open HolKernel Parse boolLib bossLib;
open arithmeticTheory listTheory optionTheory;

val isUnicodeScalar_def = new_definition (
  "isUnicodeScalar_def",
  ``isUnicodeScalar (c : num) <=>
      c < 1114112 /\ ~(55296 <= c /\ c <= 57343)``
);

val isUnicodeString_def = new_definition (
  "isUnicodeString_def",
  ``isUnicodeString (s : num list) <=> EVERY isUnicodeScalar s``
);

val isUpperAlpha_def = new_definition (
  "isUpperAlpha_def",
  ``isUpperAlpha (c : num) <=> 65 <= c /\ c <= 90``
);

val isLowerAlpha_def = new_definition (
  "isLowerAlpha_def",
  ``isLowerAlpha (c : num) <=> 97 <= c /\ c <= 122``
);

val isAlpha_def = new_definition (
  "isAlpha_def",
  ``isAlpha (c : num) <=> isUpperAlpha c \/ isLowerAlpha c``
);

val toLower_def = new_definition (
  "toLower_def",
  ``toLower (c : num) = if isUpperAlpha c then c + 32 else c``
);

val normalizeChar_def = new_definition (
  "normalizeChar_def",
  ``normalizeChar (c : num) =
      if isAlpha c then SOME (toLower c) else NONE``
);

val normalizeString_def = Define `
  (normalizeString ([] : num list) = ([] : num list)) /\
  (normalizeString (c::cs) =
     case normalizeChar c of
       NONE => normalizeString cs
     | SOME c' => c'::normalizeString cs)
`;

val isCleanPalindrome_precond_def = new_definition (
  "isCleanPalindrome_precond_def",
  ``isCleanPalindrome_precond (s : num list) <=> T``
);

val reverseList_def = new_definition (
  "reverseList_def",
  ``reverseList (xs : num list) = REVERSE xs``
);

val isCleanPalindrome_def = new_definition (
  "isCleanPalindrome_def",
  ``isCleanPalindrome (s : num list) =
      let norm = normalizeString s
      in
        (norm = reverseList norm)``
);

val isCleanPalindrome_postcond_def = new_definition (
  "isCleanPalindrome_postcond_def",
  ``isCleanPalindrome_postcond
      (s : num list) (result : bool) <=>
      let norm = normalizeString s
      in
        (result = T ==> norm = REVERSE norm) /\
        (result = F ==> norm <> REVERSE norm)``
);

val isCleanPalindrome_spec_satisfied =
  ``!s : num list.
      isUnicodeString s ==>
      isCleanPalindrome_precond s ==>
      isCleanPalindrome_postcond s (isCleanPalindrome s)``;

(*
  Statement-only formalization of VERINA artifact verina_advanced_20,
  cataloged as "isItEight": the executable Boolean program tests whether an
  integer is divisible by eight or has the digit eight in its absolute value.
  This file contains no proof.
*)

open HolKernel Parse boolLib bossLib;
open arithmeticTheory integerTheory;

val hasDigitEightFuel_def = Define `
  (hasDigitEightFuel 0 (m : num) = F) /\
  (hasDigitEightFuel (SUC fuel) m =
     if m <= 0 then
       F
     else if m MOD 10 = 8 then
       T
     else
       hasDigitEightFuel fuel (m DIV 10))
`;

val hasDigitEight_def = new_definition (
  "hasDigitEight_def",
  ``hasDigitEight (m : num) = hasDigitEightFuel m m``
);

val isItEight_precond_def = new_definition (
  "isItEight_precond_def",
  ``isItEight_precond (n : int) <=> T``
);

val isItEight_def = new_definition (
  "isItEight_def",
  ``isItEight (n : int) =
      let absN = Num (ABS n)
      in
        (n % 8 = 0 \/ hasDigitEight absN)``
);

val isItEight_postcond_def = new_definition (
  "isItEight_postcond_def",
  ``isItEight_postcond (n : int) (result : bool) <=>
      let absN = Num (ABS n)
      in
        ((n % 8 = 0 \/
          ?i : num. (absN DIV (10 EXP i)) MOD 10 = 8) <=>
         result)``
);

val isItEight_spec_satisfied =
  ``!n : int.
      isItEight_precond n ==>
      isItEight_postcond n (isItEight n)``;

(*
