  ``maxOfList_postcond
      (lst : num list) (result : num) <=>
      MEM result lst /\
      !x : num. MEM x lst ==> x <= result``
);

val maxOfList_spec_satisfied =
  ``!lst : num list.
      maxOfList_precond lst ==>
      maxOfList_postcond lst (maxOfList lst)``;

